/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// The request was refused under one of this SERVICE's own documented error codes:
    /// see the two parameter variants below.
    ValidationException(ValidationException),
    /// A parameter the request had to carry was not supplied. Renders as HTTP 400 with
    /// the error code `MissingParameter`.
    ///
    /// Deliberately NOT the `ValidationException` above: `MissingParameter` is the code
    /// Amazon SQS itself answers a request that leaves out a required parameter, and
    /// this model declares the shape for no operation, so this wrapper is the only
    /// channel that can carry it.
    MissingParameter(MissingParameter),
    /// A parameter's VALUE is not one this service accepts. Renders as HTTP 400 with the
    /// error code `InvalidParameterValue`.
    ///
    /// Deliberately NOT the `ValidationException` above: `InvalidParameterValue` is the
    /// code Amazon SQS itself answers a value outside what a parameter accepts, and this
    /// model declares the shape for no operation, so this wrapper is the only channel
    /// that can carry it.
    InvalidParameterValue(InvalidParameterValue),
    /// The policies in force do not permit this call. Renders as HTTP 403 with the error
    /// code `AccessDenied`.
    ///
    /// Deliberately NOT a modeled variant: the authorization refusal is the AWS-common
    /// one, and this model declares no shape for it, so this wrapper is the only channel
    /// that can carry it.
    AccessDenied(AccessDenied),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// NOT the channel for this service: Amazon SQS has no `ValidationException` shape,
    /// and a parameter-level refusal it answers under a code outside its API is one no
    /// client can classify. Use [`Scaffolded::missing_parameter`] or
    /// [`Scaffolded::invalid_parameter_value`] — whose messages come from the templates
    /// in `crate::state` — and keep this for a service that has no documented code for
    /// the fault at all.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }

    /// Refuse the request with HTTP 400 `MissingParameter`, naming the parameter it had
    /// to carry and did not (see [`Scaffolded::MissingParameter`]).
    pub fn missing_parameter(parameter: &str) -> Self {
        Self::MissingParameter(MissingParameter::new(parameter))
    }

    /// Refuse the request with HTTP 400 `InvalidParameterValue`, saying which value was
    /// not accepted and what the parameter takes (see
    /// [`Scaffolded::InvalidParameterValue`]).
    pub fn invalid_parameter_value(message: impl Into<String>) -> Self {
        Self::InvalidParameterValue(InvalidParameterValue::new(message))
    }

    /// Refuse the request with HTTP 403 `AccessDenied`, carrying the refusal the
    /// authorization gate built from the principal, the action and the resource the
    /// decision was made about (see [`Scaffolded::AccessDenied`]).
    pub fn access_denied(message: impl Into<String>) -> Self {
        Self::AccessDenied(AccessDenied::new(message))
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
            Self::MissingParameter(e) => write!(f, "{e}"),
            Self::InvalidParameterValue(e) => write!(f, "{e}"),
            Self::AccessDenied(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::ValidationException(e) => e.source(),
            Self::MissingParameter(e) => e.source(),
            Self::InvalidParameterValue(e) => e.source(),
            Self::AccessDenied(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            Self::ValidationException(e) => e,
            Self::MissingParameter(e) => e,
            Self::InvalidParameterValue(e) => e,
            Self::AccessDenied(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
            Self::MissingParameter(_) => &MISSING_PARAMETER_SCHEMA,
            Self::InvalidParameterValue(_) => &INVALID_PARAMETER_VALUE_SCHEMA,
            Self::AccessDenied(_) => &ACCESS_DENIED_SCHEMA,
        }
    }

    /// The error SHAPE this failure names (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literals as they are: changing one changes what clients match on. They are
    /// intentionally not tied to the Rust variant names.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            Self::ValidationException(_) => "ValidationException",
            // A parameter-level refusal is raised by the request validation framework in
            // front of this service, so the shape it names is that framework's, not one of
            // this model's. The legacy query code for the same class travels in the
            // `x-amzn-query-error` header ([`Self::query_error_code`]) and a batch result
            // entry reports it per entry, which is why both names exist.
            Self::MissingParameter(_) => MISSING_PARAMETER_SHAPE_ID,
            Self::InvalidParameterValue(_) => INVALID_PARAMETER_VALUE_SHAPE_ID,
            Self::AccessDenied(_) => ACCESS_DENIED,
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            Self::ValidationException(_) => 400,
            Self::MissingParameter(_) => 400,
            Self::InvalidParameterValue(_) => 400,
            Self::AccessDenied(_) => ACCESS_DENIED_STATUS,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            // The model's own code for the class where it states one, and the error
            // shape's own name where it DEFAULTS that binding (`InvalidAttributeName`,
            // `InvalidAttributeValue`, `InvalidMessageContents`, `InvalidIdFormat`): a
            // query-era client knows such a class by its name, and the shape name is what
            // this service's wire code for it already is.
            Self::Modeled(e) => e.query_error_code().or_else(|| Some(e.shape_name())),
            // Same reason as the scaffold signal: the synthetic shape carries no
            // `awsQueryError` trait.
            Self::ValidationException(_) => None,
            // The legacy query code of a parameter-level refusal, which is NOT the shape
            // id [`Self::shape_name`] answers for it: the class is named by its Coral
            // shape in the body and by this code in the `x-amzn-query-error` header, so a
            // client still speaking the query vocabulary can recover it. The same pair a
            // batch result entry reports per entry.
            Self::MissingParameter(_) => Some(MISSING_PARAMETER),
            Self::InvalidParameterValue(_) => Some(INVALID_PARAMETER_VALUE),
            Self::AccessDenied(_) => Some(ACCESS_DENIED),
        }
    }
}
